// Simuliert exakt die Lade- und Konflikt-Logik von app/page.tsx gegen das echte Backend,
// weil hier kein Browser zur Verfügung steht, um die Seite visuell zu prüfen.
const BASE = "http://localhost:8000";

const scenarios = await fetch(`${BASE}/api/scenarios`).then((r) => r.json());
const scenarioId = scenarios.some((s) => s.id === "G60-US") ? "G60-US" : scenarios[0].id;

const [requirements, signals] = await Promise.all([
  fetch(`${BASE}/api/scenarios/${scenarioId}/requirements`).then((r) => r.json()),
  fetch(`${BASE}/api/scenarios/${scenarioId}/signals`).then((r) => r.json()),
]);

const signalsById = new Map(signals.map((s) => [s.id, s]));

function conflictingTitlesFor(requirement) {
  const titles = [];
  for (const signalId of requirement.signal_ids) {
    const signal = signalsById.get(signalId);
    for (const otherId of signal?.conflicts_with ?? []) {
      titles.push(signalsById.get(otherId)?.title ?? otherId);
    }
  }
  return titles;
}

console.log(`Scenario: ${scenarioId}, ${requirements.length} requirements, ${signals.length} signals`);
for (const req of requirements) {
  const conflicts = conflictingTitlesFor(req);
  console.log(
    `#${req.rank} ${req.title} | score=${req.score} | evidence=${req.evidence_level} | status=${req.status} | category=${req.category} | conflicts=${JSON.stringify(conflicts)}`
  );
}

